    assign m3_axi_awcache = 4'b0011; assign m3_axi_awprot = 3'b000; assign m3_axi_awqos = 4'b0;
    assign m3_axi_awvalid = 1'b0; assign m3_axi_wdata = 128'b0; assign m3_axi_wstrb = 16'b0;
    assign m3_axi_wlast = 1'b0; assign m3_axi_wvalid = 1'b0; assign m3_axi_bready = 1'b1;

    axi_rd_probe #(.AW(AW), .IDW(IDW)) u_m4 (
        .clk(clk), .rst(rst), .go(go_pulse), .enable(enable[4]),
        .base(base64[AW-1:0] + 4 * {17'd0, stride}), .beats(beats), .burst(burst_r[8:0]), .step(step_r),
        .maxout(maxout_r[7:0]), .nids(nids_r[6:0]), .qos(axparam[3:0]), .cache(axparam[7:4]),
        .done(done_v[4]), .cycles(cyc_v[4]), .rcv_beats(rcv_v[4]),
        .err_count(err_v[4]), .xsum(xs_v[4]),
        .arid(m4_axi_arid), .araddr(m4_axi_araddr), .arlen(m4_axi_arlen),
        .arsize(m4_axi_arsize), .arburst(m4_axi_arburst), .arlock(m4_axi_arlock),
        .arcache(m4_axi_arcache), .arprot(m4_axi_arprot), .arqos(m4_axi_arqos),
        .arvalid(m4_axi_arvalid), .arready(m4_axi_arready),
        .rid(m4_axi_rid), .rdata(m4_axi_rdata), .rresp(m4_axi_rresp),
        .rlast(m4_axi_rlast), .rvalid(m4_axi_rvalid), .rready(m4_axi_rready));
    assign m4_axi_awid = 0;   assign m4_axi_awaddr = 0;  assign m4_axi_awlen = 0;
    assign m4_axi_awsize = 3'b100; assign m4_axi_awburst = 2'b01; assign m4_axi_awlock = 1'b0;
    assign m4_axi_awcache = 4'b0011; assign m4_axi_awprot = 3'b000; assign m4_axi_awqos = 4'b0;
    assign m4_axi_awvalid = 1'b0; assign m4_axi_wdata = 128'b0; assign m4_axi_wstrb = 16'b0;
    assign m4_axi_wlast = 1'b0; assign m4_axi_wvalid = 1'b0; assign m4_axi_bready = 1'b1;

    axi_rd_probe #(.AW(AW), .IDW(IDW)) u_m5 (
        .clk(clk), .rst(rst), .go(go_pulse), .enable(enable[5]),
        .base(base64[AW-1:0] + 5 * {17'd0, stride}), .beats(beats), .burst(burst_r[8:0]), .step(step_r),
        .maxout(maxout_r[7:0]), .nids(nids_r[6:0]), .qos(axparam[3:0]), .cache(axparam[7:4]),
        .done(done_v[5]), .cycles(cyc_v[5]), .rcv_beats(rcv_v[5]),
        .err_count(err_v[5]), .xsum(xs_v[5]),
        .arid(m5_axi_arid), .araddr(m5_axi_araddr), .arlen(m5_axi_arlen),
        .arsize(m5_axi_arsize), .arburst(m5_axi_arburst), .arlock(m5_axi_arlock),
        .arcache(m5_axi_arcache), .arprot(m5_axi_arprot), .arqos(m5_axi_arqos),
        .arvalid(m5_axi_arvalid), .arready(m5_axi_arready),
        .rid(m5_axi_rid), .rdata(m5_axi_rdata), .rresp(m5_axi_rresp),
        .rlast(m5_axi_rlast), .rvalid(m5_axi_rvalid), .rready(m5_axi_rready));
    assign m5_axi_awid = 0;   assign m5_axi_awaddr = 0;  assign m5_axi_awlen = 0;
    assign m5_axi_awsize = 3'b100; assign m5_axi_awburst = 2'b01; assign m5_axi_awlock = 1'b0;
    assign m5_axi_awcache = 4'b0011; assign m5_axi_awprot = 3'b000; assign m5_axi_awqos = 4'b0;
    assign m5_axi_awvalid = 1'b0; assign m5_axi_wdata = 128'b0; assign m5_axi_wstrb = 16'b0;
    assign m5_axi_wlast = 1'b0; assign m5_axi_wvalid = 1'b0; assign m5_axi_bready = 1'b1;

    // global go -> all-done cycle counter
    reg        busy;
    reg [63:0] gcyc;
    wire all_done = &(done_v | ~enable);
    always @(posedge clk) begin
        if (rst) begin busy <= 1'b0; gcyc <= 0; end
        else if (go_pulse) begin busy <= 1'b1; gcyc <= 0; end
        else if (busy) begin
            if (all_done) busy <= 1'b0; else gcyc <= gcyc + 64'd1;
        end
    end

    // ---------------- AXI-Lite read ----------------
    reg [C_S_AXI_ADDR_WIDTH-3:0] aridx;
    reg [31:0] rd_mux;
    wire [2:0] sub = aridx[2:0];
    wire [4:0] mi  = aridx[7:3] - 5'd8;   // 0x100 >> 5 = 8
    integer k;
    always @(*) begin
        rd_mux = 32'b0;
        case (aridx)
            8'h01: rd_mux = {15'b0, busy, {(16-NM){1'b0}}, done_v};
            8'h02: rd_mux = enable;
            8'h03: rd_mux = base_lo;   8'h04: rd_mux = base_hi;
            8'h05: rd_mux = stride;    8'h06: rd_mux = beats;
            8'h07: rd_mux = burst_r;   8'h08: rd_mux = maxout_r;
            8'h09: rd_mux = nids_r;
            8'h0A: rd_mux = gcyc[31:0]; 8'h0B: rd_mux = gcyc[63:32];
            8'h0C: rd_mux = 32'h42575052;   // "BWPR"
            8'h0D: rd_mux = NM;
            8'h0E: rd_mux = axparam;
            8'h0F: rd_mux = step_r;
            default: ;
        endcase
        for (k = 0; k < NM; k = k + 1) begin
            if (aridx[7:3] == 8 + k) begin
                case (sub)
                    3'd0: rd_mux = cyc_v[k][31:0];
                    3'd1: rd_mux = cyc_v[k][63:32];
                    3'd2: rd_mux = rcv_v[k];
                    3'd3: rd_mux = err_v[k];
                    3'd4: rd_mux = xs_v[k][31:0];
                    3'd5: rd_mux = xs_v[k][63:32];
                    3'd6: rd_mux = xs_v[k][95:64];
                    3'd7: rd_mux = xs_v[k][127:96];
                endcase
            end
        end
    end

    always @(posedge clk) begin
        if (!aresetn) begin
            S_AXI_ARREADY <= 1'b0; S_AXI_RVALID <= 1'b0; S_AXI_RRESP <= 2'b00;
            S_AXI_RDATA <= 32'b0; aridx <= 0;
        end else begin
            if (S_AXI_ARVALID && !S_AXI_ARREADY && !S_AXI_RVALID) begin
                S_AXI_ARREADY <= 1'b1; aridx <= S_AXI_ARADDR[C_S_AXI_ADDR_WIDTH-1:2];
            end else S_AXI_ARREADY <= 1'b0;
            if (S_AXI_ARREADY) begin
                S_AXI_RVALID <= 1'b1; S_AXI_RRESP <= 2'b00; S_AXI_RDATA <= rd_mux;
            end else if (S_AXI_RVALID && S_AXI_RREADY) begin
                S_AXI_RVALID <= 1'b0;
            end
        end
    end
endmodule
